TN.defSec("endocrine",{"hypoglycemia-diabetic":{"id":"hypoglycemia-diabetic","variants":[{"id":"hypoglycemia-responsive","o":{"L":[{"t":"Blood glucose (repeat every 30 min initially for rebound)"}],"S":[{"t":"50% dextrose 50 mL IV if altered mental status; glucagon 1 mg IM or SC if no IV access"},{"t":"10% dextrose infusion if needed to maintain glucose > 100 mg/dL"}],"T":[{"t":"Carbohydrate meal when tolerating PO; repeat glucose every 30 min initially"}],"Co":[{"t":"Discharge with instructions to continue carbohydrate intake and monitor glucose if rapid response and short-acting insulin; admit for long-acting insulin / sulfonylurea / persistent neuroglycopenia"}]},"name":"Hypoglycemia, insulin-related, responds rapidly","level":"II","imp":"Hypoglycemia (insulin-related)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"مرد ۵۵ ساله دیابتی با انسولین، با تعریق و لرزش؛ قند 42 که پس از D50 هوشیار شد.","why":"گلوکز و غذا؛ قند هر 30 دقیقه."},{"id":"hypoglycemia-sulfonylurea","o":{"L":[{"t":"Blood glucose every 30 min initially (hourly after stable); electrolytes, BUN, creatinine; liver function"}],"S":[{"t":"50% dextrose 50 mL IV, then 10% dextrose infusion to maintain glucose > 100 mg/dL"},{"t":"Octreotide 50–100 µg SC; continuous infusion 125 µg/h may be required (sulfonylurea refractory)"},{"t":"Glucagon 1 mg IM / SC if no IV access"}],"T":[{"t":"Monitor for rebound hypoglycemia"}],"Co":[{"t":"Admit (risk of rebound from sulfonylureas or long-acting insulins)"}]},"name":"Refractory hypoglycemia — sulfonylurea or long-acting insulin","level":"I","imp":"Hypoglycemia, sulfonylurea / long-acting insulin, risk of rebound","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"زن ۷۰ ساله مصرف‌کننده glyburide با کما و قند 28؛ پس از D50 مجدداً افت قند.","why":"octreotide برای مهار ترشح انسولین؛ بستری."}],"ch":"129","name":"Hypoglycemia in diabetes","name_fa":"هیپوگلیسمی در دیابت","cc":["metabolic","altered-mental-status","seizure"],"keywords":"hypoglycemia, insulin reaction, sulfonylurea, octreotide, glucagon, dextrose, D50, هیپوگلیسمی, انسولین","status":"draft","features":["معمولاً عارضه درمان با انسولین یا سولفونیل‌اوره (chlorpropamide، glyburide، glipizide)؛ بعید با glitazone، glinide، مهارکننده α-glucosidase و تقریباً هرگز با metformin، آنالوگ incretin و pramlintide","تعریق، لرزش، اضطراب، تهوع، سرگیجه، تپش قلب، تکلم نامفهوم، تاری دید، سردرد، تشنج، نقص عصبی کانونی و تغییر هوشیاری از گیجی تا کما","تشخیص: قند پایین هنگام علائم و رفع آن با درمان؛ به‌راحتی به‌اشتباه بیماری عصبی/روانی تشخیص داده می‌شود؛ افتراق: سکته، تشنج، ضربه سر، MS، سایکوز، افسردگی، مسمومیت الکل/دارو"],"ddx":[{"n":"Stroke / seizure disorder / head injury |","cm":1},{"n":"Psychosis / depression |"},{"n":"Alcohol or drug intoxication |"}],"redflags":["کما یا تشنج، سولفونیل‌اوره یا انسولین طولانی‌اثر (عود)، نقص کانونی که با درمان رفع نمی‌شود"],"guide":"گلوکز: وعده کربوهیدرات اگر تحمل PO؛ تغییر هوشیاری: D50W 50 mL IV؛ انفوزیون D10 در صورت نیاز برای قند > 100 mg/dL. glucagon 1 mg IM/SC اگر IV نیست. هیپوگلیسمی مقاوم ناشی از سولفونیل‌اوره: octreotide 50 تا 100 µg SC و گاه انفوزیون 125 µg/h. قند هر 30 دقیقه در ابتدا برای هیپوگلیسمی ریباند. ترخیص بسته به پاسخ، علت، بیماری همراه و وضعیت اجتماعی؛ بیشتر واکنش‌های انسولین سریع پاسخ می‌دهند؛ ترخیص با دستور ادامه کربوهیدرات و پایش قند؛ سولفونیل‌اوره یا انسولین طولانی‌اثر: بستری. معیارهای بستری (جدول 129-1): دکمپانساسیون متابولیک تهدیدکننده، عوارض مزمن شدید/بیماری حاد/وضعیت اجتماعی نامناسب، قند > 400 با کم‌آبی شدید یا مقاوم، هیپوگلیسمی با نوروگلیکوپنی که سریعاً رفع نمی‌شود، داروی خوراکی طولانی‌اثر، تب بدون منبع در دیابت کنترل نشده.","section":"endocrine","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 129: Diabetic Emergencies, pp. 701–708"},"diabetic-ketoacidosis":{"id":"diabetic-ketoacidosis","variants":[{"id":"dka-main","o":{"I":[{"t":"CXR PA / portable (precipitant: pneumonia); other imaging per suspected cause"}],"L":[{"t":"Venous blood gas (pH), glucose (hourly), electrolytes with anion gap (every 2 h initially), BUN, creatinine, phosphate, calcium, magnesium, serum / urine ketones (β-hydroxybutyrate), CBC, urinalysis, pregnancy test if indicated; blood / urine cultures if infection suspected; osmolality, corrected Na","fl":[{"k":"note","v":"ECG for hyperkalemia / infarction; Foley as needed; flow sheet"}]}],"S":[{"t":"Normal saline 15–20 mL/kg/h for the first hour; then 0.45% NS at 250–500 mL/h for normo-/hypernatremia (NS at 250–500 mL/h for hyponatremia); #2 line 0.5 NS TKO","fl":[{"k":"ci","v":"caution in heart failure / renal failure; adjust to hemodynamics, hydration, urine output"}]},{"t":"Potassium per initial level (adequate urine output first): K > 5.2 hold K and recheck in 2 h; 3.3–5.2: add 20–30 mEq K per liter fluid; < 3.3: hold insulin and give K 20–30 mEq/h until > 3.3"},{"t":"Regular insulin infusion 0.1–0.14 U/kg/h (start at hour 1 after K ≥ 3.3) ; if glucose does not fall 10% (or 3 mmol/L) in first hour give 0.14 U/kg bolus and resume previous rate","fl":[{"k":"hi","v":""}]},{"t":"When glucose approaches 200 mg/dL: change to D5 0.45 NS with KCl 20–40 mEq/L and/or reduce insulin to 0.02–0.05 U/kg/h"},{"t":"Sodium bicarbonate 100 mmol in 400 mL water with 20 mEq KCl at 200 mL/h only if pH ≤ 6.9 (repeat every 2 h until pH > 7.0)"}],"T":[{"t":"Cardiac monitoring; hourly glucose; correct phosphate / Mg / Ca as needed"},{"t":"Young / new-onset diabetics: avoid excess free water; mannitol 1 g/kg at bedside for any neurologic change (cerebral edema) before CT"},{"t":"When glucose < 200, AG normal, pH > 7.3, HCO3 > 15 and able to eat: SC short- and long-acting insulin; stop IV insulin 1–2 h after SC insulin"}],"Co":[{"t":"ICU if AG > 25, glucose > 800, or significant comorbidity; floor / diabetic unit otherwise"},{"t":"Endocrinology / diabetes education"}]},"name":"Diabetic ketoacidosis (adult)","level":"I","imp":"Diabetic ketoacidosis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","o2":"if SpO2 < 94%","sc":"مرد ۲۵ ساله دیابتی نوع 1 با تهوع، درد شکم، تنفس عمیق، قند 520، pH 7.12 و HCO3 8.","why":"مایع، انسولین پس از K و تعیین علت."}],"ch":"129","name":"Diabetic ketoacidosis (DKA)","name_fa":"کتواسیدوز دیابتی (DKA)","cc":["metabolic","abdominal-pain","nausea-vomiting","altered-mental-status"],"keywords":"DKA, diabetic ketoacidosis, insulin infusion, Kussmaul, anion gap, cerebral edema, euglycemic ketoacidosis, SGLT2, کتواسیدوز دیابتی","status":"draft","features":["کمبود نسبی انسولین و افزایش هورمون‌های ضدتنظیمی → هیپرگلیسمی و کتونمی؛ علل (جدول 129-2): حذف/کاهش انسولین، قطع/انسداد کاتتر پمپ، عفونت، بارداری، هیپرتیروئیدی/فئوکروموسیتوم/Cushing، سوءمصرف (کوکائین)، داروها (استروئید، تیازید، آنتی‌سایکوتیک، سمپاتومیمتیک)، بیماری گرمایی، CVA، خونریزی GI، MI، PE، پانکراتیت، تروما، جراحی","دیورز اسمزی: کم‌آبی، هیپوتانسیون و تاکی‌کاردی؛ اسیدوز: افسردگی میوکارد، اتساع عروقی، تنفس Kussmaul؛ تهوع، استفراغ و درد شکم شایع؛ نبود تب عفونت را رد نمی‌کند؛ استون: بوی میوه‌ای نفس","تشخیص: قند > 250، anion gap > 10، بیکربنات < 15، pH < 7.3 و کتونمی/کتونوری متوسط؛ مراقب «euglycemic ketoacidosis» (قند فقط کمی بالا: تازه انسولین زده، اختلال گلوکونئوژنز (الکلی) یا مهارکننده SGLT2 مثل canagliflozin)؛ nitroprusside فقط acetoacetate را می‌سنجد و ممکن است کاذب منفی باشد (β-hydroxybutyrate بالا)","از دست رفتن Na، Cl، Ca، فسفر، Mg؛ pseudohyponatremia: به ازای هر 100 mg/dL افزایش قند، Na به اندازه 1.6 mEq/L کاهش (بعضی 2.4)؛ پتاسیم ممکن است پایین، طبیعی یا بالا؛ بیمار اسیدوتیک با K طبیعی یا پایین کمبود کل بدن شدید دارد","آزمایش: pH (وریدی کافی؛ اختلاف 0.03 با شریانی)، قند، الکترولیت، BUN، Cr، فسفر، Mg، CBC، UA (و بارداری)، ECG و CXR برای شدت و علت؛ افتراق: هیپوگلیسمی، HHS، کتواسیدوز الکلی/گرسنگی، نارسایی کلیه، اسیدوز لاکتیک و مسمومیت (سالیسیلات، متانول، اتیلن‌گلیکول، آهن، INH)"],"ddx":[{"n":"Hyperosmolar hyperglycemic state |","cm":1},{"n":"Sepsis / MI / PE / pancreatitis (precipitants) |","cm":1},{"n":"Alcoholic / starvation ketoacidosis |"},{"n":"Toxic alcohol / salicylate ingestion |"}],"redflags":["pH < 6.9، K < 3.3 یا > 5.2، تغییر هوشیاری، AG > 25، شوک، تغییر عصبی حین درمان (ادم مغز)"],"guide":"هدف: اصلاح کمبود حجم، اسید-باز و الکترولیت، انسولین و درمان علت (شکل 129-1). ساعت 0: شرح حال/معاینه مختصر؛ مانیتور؛ قند، ECG، کتون؛ IV #1: NS 15 تا 20 mL/kg/h اولین ساعت؛ IV #2: 0.5 NS TKO؛ الکترولیت، CBC، فسفات، Ca، Mg، VBG؛ کشت. ساعت 1: اگر K اولیه > 5.2: انسولین رگولار 0.1 تا 0.14 U/kg/h (بدون بولوس)؛ K بعد از 2 ساعت؛ K > 3.3 و < 5.2 با ادرار کافی: 20 تا 30 mEq K به هر لیتر مایع + انسولین؛ K < 3.3: انسولین را نگه دار و K 20 تا 30 mEq/h تا K > 3.3 سپس انسولین؛ ادرار کافی قبل از K ضروری. ساعت 2: اهداف: مایع کافی، انسولین، K 3.3 تا 5.2، کاهش قند 75 mg/dL/h، Ca/Mg/Phos؛ وقتی قند نزدیک 200: D5 0.5NS با KCl 20 تا 40 mEq/L و/یا کاهش انسولین به 0.02 تا 0.05 U/kg/h؛ pH > 6.9 نیاز به NaHCO3 ندارد. ساعت 3: قند، الکترولیت، AG، VBG؛ الکترولیت هر 2 ساعت و قند هر ساعت؛ اگر قند 10% (یا 3 mmol/L/h) کاهش نیافت پس از 1 ساعت: بولوس 0.14 U/kg و ادامه نرخ قبلی. ساعت 4 تا 12: اگر قند سریع‌تر از 50 تا 75 mg/dL/h کاهش یابد انسولین را کم کن؛ جوان و دیابت تازه‌تشخیص: از آب آزاد اضافه بپرهیز، مراقب ادم مغز و mannitol بالین. جبران کمبود طی 24 تا 36 ساعت؛ قند 180 تا 200 و ادامه انسولین ≥ 12 ساعت یا رفع DKA (قند < 200، AG طبیعی، pH > 7.3، HCO3 > 15)؛ پس از NS اولیه: اگر Na طبیعی/بالا: 0.45NS با 250 تا 500 mL/h + K؛ Na پایین: NS 250 تا 500 mL/h؛ pH < 6.9: 100 mmol NaHCO3 در 400 mL آب + 20 mEq KCl با 200 mL/h و تکرار هر 2 ساعت تا pH > 7.0 (K هر 2 ساعت). بیکربنات وقتی pH ≤ 6.9. پایش هر ساعت تا قند < 200، HCO3 ≥ 18، pH > 7.3. ادم مغز: خطر در سن پایین و دیابت جدید؛ با هر تغییر عصبی زودرس: mannitol 1 g/kg قبل از CT. بستری: AG > 25 یا قند > 800 یا بیماری همراه مهم: ICU؛ AG < 25 و قند < 800: بخش/واحد دیابت. وقتی غذا خورد: انسولین SC کوتاه و طولانی‌اثر و قطع انسولین IV 1 تا 2 ساعت بعد.","section":"endocrine","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 129: Diabetic Emergencies, pp. 701–708"},"hyperosmolar-hyperglycemic-state":{"id":"hyperosmolar-hyperglycemic-state","variants":[{"id":"hhs-main","o":{"I":[{"t":"CXR PA / portable (precipitant); CT head if focal neurologic deficits"}],"L":[{"t":"Venous blood gas (pH), glucose (hourly), electrolytes (corrected Na), BUN, creatinine, calculated osmolality, ketones, CBC, urinalysis, phosphate / Mg / Ca; blood / urine cultures; troponin; every 2 h until stable"}],"S":[{"t":"Normal saline 1.0 L/h initially; then 0.45% NS at 4–14 mL/kg/h if Na high/normal, NS at 4–14 mL/kg/h if Na low","fl":[{"k":"ci","v":"caution in heart failure / renal failure — close monitoring of volume status"}]},{"t":"Regular insulin infusion 0.1–0.14 U/kg/h (goal glucose fall 50 mg/dL/h; reduce to 0.05 U/kg/h if > 70/h; increase to 0.14–0.20 U/kg/h if < 50/h)","fl":[{"k":"hi","v":""}]},{"t":"When glucose ≤ 300 mg/dL: D5 0.45 NS and insulin 0.05 U/kg/h to keep glucose 200–250 until osmolality ≤ 315"},{"t":"Potassium: K < 3.3: 40 mEq until ≥ 3.3; K 3.3–< 5.0: replace to 4–5 mEq/L; K ≥ 5.0: none, check every 1–2 h"}],"T":[{"t":"Cardiac monitoring; search for and treat precipitating cause (infection, MI, stroke)"},{"t":"After resolution: SC insulin as needed"}],"Co":[{"t":"ICU / monitored admission; endocrinology"}]},"name":"Hyperosmolar hyperglycemic state","level":"I","imp":"Hyperosmolar hyperglycemic state","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","o2":"if SpO2 < 94%","sc":"زن ۷۸ ساله دیابتی نوع 2 با ضعف و گیجی چند روزه، قند 880، Na 150 و اسمولالیته 350.","why":"مایع تهاجمی (NS 1 L/h)، انسولین و K؛ علت را بجو."}],"ch":"129","name":"Hyperosmolar hyperglycemic state (HHS)","name_fa":"حالت هیپراسمولار هیپرگلیسمیک (HHS)","cc":["metabolic","altered-mental-status","weakness"],"keywords":"HHS, hyperosmolar hyperglycemic, HONK, hyperosmolar, type 2 diabetes, dehydration, هیپراسمولار, کمای هیپراسمولار","status":"draft","features":["دیابت نوع 2؛ علل مشابه DKA؛ کمبود/مقاومت انسولین + استرس فیزیولوژیک ← التهاب و هورمون‌های ضدتنظیمی ← هیپرگلیسمی؛ دیورز اسمزی ← هیپوولمی و از دست رفتن الکترولیت","بیمار معمول: سالمند دیابتی نوع 2 با ضعف، تنگی نفس، درد قفسه/شکم یا تغییر هوشیاری و بیماری ریه/قلب/کلیه/عصبی قبلی؛ علائم کم‌آبی با ارتواستاز، پوست و مخاط خشک و تغییر هوشیاری؛ نقص کانونی و تشنج ممکن","تشخیص: قند > 600، اسمولالیته محاسبه‌شده (Osm = 2[Na] + glucose/18) > 315 mOsm/kg، HCO3 > 15، pH > 7.3 و کتون منفی تا کمی مثبت؛ بالا بودن شدید قند و اسمولالیته و نبود کتوز قابل‌توجه HHS را از DKA جدا می‌کند؛ بقیه آزمایش‌ها مثل DKA"],"ddx":[{"n":"DKA |","cm":1},{"n":"Sepsis / stroke / MI precipitant |","cm":1},{"n":"Uremia / other cause of AMS |"}],"redflags":["اسمولالیته > 320، تغییر هوشیاری شدید، شوک، تشنج"],"guide":"اصلاح کمبود حجم، الکترولیت، هیپراسمولالیته و درمان علت (شکل 129-2). مایع: NS 1.0 L/h؛ سپس بر اساس Na اصلاح‌شده و هیدراتاسیون: Na بالا/طبیعی: 0.45NS با 4 تا 14 mL/kg/h؛ Na پایین: NS 4 تا 14 mL/kg/h. انسولین: انفوزیون IV 0.1 تا 0.14 U/kg/h؛ هدف کاهش قند 50 mg/dL/h؛ اگر > 70 mg/dL/h کاهش: انسولین 0.05 U/kg/h؛ اگر < 50: افزایش به 0.14 تا 0.20 U/kg/h. وقتی قند ≤ 300: تغییر به D5 0.45NS و انسولین 0.05 U/kg/h تا قند 200 تا 250 تا اسمولالیته ≤ 315. پتاسیم: K < 3.3: 40 mEq تا ≥ 3.3؛ K ≥ 5.0: بدون K و پایش هر 1 تا 2 ساعت؛ K 3.3 تا < 5.0: K برای حفظ 4 تا 5 (غلظت ≥ 20 mEq/L از خط مرکزی). الکترولیت، BUN، Cr و قند هر 2 ساعت تا پایداری؛ پس از رفع، انسولین SC. معیارهای بستری جدول 129-1.","section":"endocrine","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 129: Diabetic Emergencies, pp. 701–708"},"diabetic-foot-infection":{"id":"diabetic-foot-infection","variants":[{"id":"dfi-non-limb-threatening","o":{"I":[{"t":"Foot radiograph (osteomyelitis / gas / foreign body); MRI or nuclear scan as indicated"}],"L":[{"t":"CBC with differential, ESR, comprehensive metabolic panel (glucose); culture from base of ulcer (tissue specimen if possible)"}],"A":[{"t":"Cephalexin 500 mg PO every 6 h for 10 days","fl":[{"k":"note","v":"or clindamycin 300–450 mg PO every 6–8 h, dicloxacillin 500 mg PO every 6 h, amoxicillin-clavulanate 875/125 mg PO every 12 h, or clarithromycin 500 mg PO every 12 h in severe penicillin allergy"}]}],"T":[{"t":"Debridement of all necrotic tissue and callus; wound care / dressing; appropriate off-loading of weight-bearing; tetanus update"}],"Co":[{"t":"Podiatry follow-up; outpatient follow-up in 24–72 h; admit if infection progresses or systemic signs"}]},"name":"Diabetic foot ulcer, non-limb-threatening infection (outpatient)","level":"III","imp":"Diabetic foot ulcer, non-limb-threatening infection","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۵۸ ساله دیابتی با زخم سطحی پاشنه، سلولیت 1 cm، بدون تب و بدون رسیدن به استخوان.","why":"آنتی‌بیوتیک خوراکی، دبریدمان، off-loading و پیگیری."},{"id":"dfi-limb-threatening","o":{"I":[{"t":"Foot radiograph, MRI / nuclear scan / bone scan as indicated; arteriography / vascular imaging if ischemia; CXR portable"}],"L":[{"t":"CBC with differential, ESR, comprehensive metabolic panel, lactate, blood cultures; deep culture from base of ulcer / wound (tissue)"}],"S":[{"t":"IV fluid resuscitation if sepsis","fl":[{"k":"ci","v":"caution in heart failure / CKD"}]},{"t":"Glucose control (insulin) as needed"}],"A":[{"t":"Limb-threatening: ampicillin-sulbactam 3 g IV every 6 h, or piperacillin-tazobactam 4.5 g IV every 6–8 h, or clindamycin 900 mg IV every 6 h plus (ciprofloxacin 400 mg IV every 8–12 h or ceftriaxone 1 g IV every 12 h)","fl":[{"k":"hi","v":""}]},{"t":"Life-threatening: imipenem-cilastatin 500 mg IV every 6 h, or meropenem 1 g IV every 8 h, or vancomycin 15–20 mg/kg IV every 12 h plus metronidazole 500 mg IV every 8 h plus aztreonam 2 g IV every 6–8 h or ciprofloxacin 400 mg IV every 8–12 h (if MRSA coverage warranted)","fl":[{"k":"note","v":"adjust dosages for renal / hepatic function"}]}],"T":[{"t":"Surgical debridement with resection of necrotic bone and soft tissue; exploration and drainage of deep abscess; wound care; tetanus update"}],"Co":[{"t":"Hospital admission; surgery (podiatric / orthopedic / vascular); infectious disease; endocrinology"}]},"name":"Limb- or life-threatening diabetic foot infection (deep ulcer, > 2 cm cellulitis, fever, ischemia, sepsis)","level":"I","imp":"Diabetic foot infection, limb- / life-threatening","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"مرد ۶۵ ساله دیابتی با زخم عمیق و بدبوی پا، سلولیت بالای مچ، تب 39 و فشار 90/55.","why":"آنتی‌بیوتیک IV وسیع‌الطیف و دبریدمان جراحی فوری."}],"ch":"129","name":"Diabetic foot ulcer and infection","name_fa":"زخم و عفونت پای دیابتی","cc":["wound-bite","joint-limb-pain","fever"],"keywords":"diabetic foot ulcer, diabetic foot infection, osteomyelitis, limb-threatening, ampicillin-sulbactam, piperacillin-tazobactam, پای دیابتی","status":"draft","features":["طبقه‌بندی: غیرتهدیدکننده اندام، تهدیدکننده اندام، تهدیدکننده حیات (جدول 129-3)","غیرتهدیدکننده: سلولیت < 2 cm، زخم سطحی، عفونت خفیف، بدون سمیت سیستمیک، بدون تغییر ایسکمیک، بدون درگیری استخوان/مفصل؛ نمی‌رسد به استخوان","تهدیدکننده اندام/حیات: سلولیت > 2 cm، زخم عمیق، بو یا ترشح چرکی، تب، تغییرات ایسکمیک، لنفانژیت، ادم، سپسیس یا شوک سپتیک"],"ddx":[{"n":"Osteomyelitis |","cm":1},{"n":"Necrotizing soft tissue infection / gas gangrene |","cm":1},{"n":"Charcot neuroarthropathy / critical limb ischemia |"}],"redflags":["تب، سپسیس، عمق به استخوان، ایسکمی، گانگرن، گاز در نسج"],"guide":"غیرتهدیدکننده: سرپایی با پیگیری 24 تا 72 ساعت؛ دبریدمان نکروز و کالوس، مراقبت زخم/پانسمان، آنتی‌بیوتیک تجربی (اصلاح با کشت)، off-loading؛ بستری اگر پیشرفت یا علائم سیستمیک؛ ارجاع پودیاتری. تهدیدکننده: بستری، دبریدمان جراحی و برداشتن استخوان و بافت نرم نکروتیک، تخلیه آبسه عمیق، آنتی‌بیوتیک تجربی، رزکسیون استئومیلیت، جراحی ترمیمی. آنتی‌بیوتیک (جدول 129-4): غیرتهدیدکننده (10 روز): cephalexin 500 mg PO هر 6 ساعت یا clindamycin 300 تا 450 mg PO هر 6 تا 8 ساعت یا dicloxacillin 500 mg PO هر 6 ساعت یا amoxicillin-clavulanate 875/125 mg PO هر 12 ساعت یا clarithromycin 500 mg PO هر 12 ساعت (آلرژی شدید به پنی‌سیلین)؛ تهدیدکننده اندام: خوراکی (با پیگیری نزدیک): (ciprofloxacin یا levofloxacin یا moxifloxacin) + clindamycin یا TMP-SMX + amoxicillin-clavulanate؛ IV: ampicillin-sulbactam 3 g هر 6 ساعت یا piperacillin-tazobactam 4.5 g هر 6 تا 8 ساعت یا clindamycin 900 mg هر 6 ساعت + (ciprofloxacin 400 mg هر 8 تا 12 ساعت یا ceftriaxone 1 g هر 12 ساعت)؛ تهدیدکننده حیات: imipenem-cilastatin 500 mg هر 6 ساعت یا meropenem 1 g هر 8 ساعت یا vancomycin 15 تا 20 mg/kg هر 12 ساعت + metronidazole 500 mg هر 8 ساعت + aztreonam 2 g هر 6 تا 8 ساعت یا ciprofloxacin 400 mg هر 8 تا 12 ساعت (در صورت نیاز به پوشش MRSA)؛ دوزها با عملکرد کلیه/کبد تنظیم شود.","section":"endocrine","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 129: Diabetic Emergencies, pp. 701–708"},"alcoholic-ketoacidosis":{"id":"alcoholic-ketoacidosis","variants":[{"id":"aka-main","o":{"L":[{"t":"Venous blood gas, glucose, electrolytes with anion gap, BUN, creatinine, serum ketones (β-hydroxybutyrate; nitroprusside may be falsely negative), lactate, magnesium, phosphate, liver enzymes, lipase, ethanol level; osmolal gap if toxic alcohol considered"}],"S":[{"t":"Thiamine 100 mg IV before glucose administration"},{"t":"D5NS IV until rehydrated, then D5 0.45NS for maintenance","fl":[{"k":"ci","v":"caution in AKI / anuria / heart failure"}]},{"t":"Supplement electrolytes (K, Mg, phosphate) and other vitamins as indicated"},{"t":"Sodium bicarbonate if pH remains < 7.0 despite treatment"}],"T":[{"t":"Continue treatment until the acidosis clears and oral intake tolerated ; consider other causes if gap does not close","fl":[{"k":"note","v":"no insulin, unlike DKA"}]}],"Co":[{"t":"Admit; addiction medicine / psychiatry as needed"}]},"name":"Alcoholic ketoacidosis","level":"II","imp":"Alcoholic ketoacidosis","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"once","cxr":"none","sc":"مرد ۴۵ ساله الکلی پس از binge با تهوع، استفراغ، درد شکم، تنفس عمیق، قند 90 و gap 28.","why":"D5NS و thiamine؛ بدون انسولین."}],"ch":"130","name":"Alcoholic ketoacidosis (AKA)","name_fa":"کتواسیدوز الکلی (AKA)","cc":["metabolic","abdominal-pain","nausea-vomiting"],"keywords":"alcoholic ketoacidosis, AKA, anion gap, thiamine, D5NS, MUDPILES, کتواسیدوز الکلی","status":"draft","features":["پس از مصرف شدید الکل (حاد یا مزمن): تخلیه ذخایر گلیکوژن ← لیپولیز ← کتواسیدها ← اسیدوز متابولیک anion gap","تهوع، استفراغ و درد شکم پس از مصرف شدید الکل؛ ظاهر بیمار، کم‌آب و حساسیت غیراختصاصی شکم یا ناشی از گاستریت، هپاتیت یا پانکراتیت","اسیدوز متابولیک anion gap؛ pH متغیر (اختلال مختلط: اسیدوز AKA + آلکالوز متابولیک ناشی از استفراغ)؛ قند پایین تا کمی بالا؛ سطح الکل معمولاً پایین یا غیرقابل‌تشخیص؛ کتون، acetoacetate و β-hydroxybutyrate بالا (nitroprusside فقط acetoacetate را می‌سنجد و ممکن است کاذب پایین/منفی باشد)","معیارها (جدول 130-1): قند پایین/طبیعی/کمی بالا، binge drinking با تهوع و استفراغ و کاهش دریافت، اسیدوز anion gap بالا، کتون سرمی مثبت (نبود کتون با nitroprusside رد نمی‌کند)، اسیدوز بدون توضیح دیگر؛ افتراق MUDPILES: Methanol، Uremia، DKA، Paraldehyde، Iron/isoniazid/inhalants، Lactic acidosis، Ethanol/ethylene glycol، Salicylates"],"ddx":[{"n":"DKA |","cm":1},{"n":"Toxic alcohols / salicylate (MUDPILES) |","cm":1},{"n":"Pancreatitis / gastritis / hepatitis |"},{"n":"Lactic acidosis / uremia |"}],"redflags":["pH < 7.0، gap که با درمان بسته نمی‌شود، علائم Wernicke"],"guide":"D5NS IV تا هیدراته شدن سپس D5 0.45NS نگهدارنده؛ کریستالوئید ایزوتونیک حجم را برمی‌گرداند؛ گلوکز ترشح انسولین درونزا را تحریک و کتوز را مهار می‌کند (انسولین مثل DKA تجویز نمی‌شود). thiamine 100 mg IV قبل از گلوکز برای جلوگیری از Wernicke. جایگزینی الکترولیت و ویتامین‌ها. ادامه تا رفع اسیدوز و تحمل خوراکی. اگر gap بسته نشد علل دیگر را در نظر بگیر. sodium bicarbonate اگر علی‌رغم درمان pH < 7.0.","section":"endocrine","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 130: Alcoholic Ketoacidosis, pp. 709–710"},"myxedema-coma":{"id":"myxedema-coma","variants":[{"id":"myxedema-main","o":{"I":[{"t":"CXR portable (pneumonia / effusion / heart size); CT head if focal / other cause suspected"}],"L":[{"t":"Free T4, free T3, TSH (do not delay treatment); random cortisol; glucose, electrolytes (hyponatremia), blood gas (hypercapnia), CBC, lactate, creatinine, CK, troponin; blood / urine cultures"}],"S":[{"t":"Hydrocortisone 100 mg IV (suspected adrenal insufficiency)","fl":[{"k":"hi","v":""}]},{"t":"Levothyroxine (T4) 4 µg/kg IV, then 100 µg IV at 24 h, then 50 µg IV until oral tolerated — or liothyronine (T3) 20 µg IV then 10 µg IV every 8 h for severe myxedema coma","fl":[{"k":"ci","v":"elderly / cardiovascular disease: start with no more than 10 µg IV T3"}]},{"t":"Dextrose to correct hypoglycemia; IV fluid resuscitation for hypotension","fl":[{"k":"ci","v":"caution in heart failure; vasopressors may be ineffective until thyroid hormone replaced"}]}],"T":[{"t":"Airway stabilization and mechanical ventilation as needed (difficult airway: macroglossia / glottic edema); cardiac monitoring"},{"t":"Passive rewarming for hypothermia; identify and treat precipitating factors (infection, sedatives, cold, MI, CVA, GI bleed)"}],"A":[{"t":"Empiric antibiotics if infection suspected after cultures"}],"Co":[{"t":"ICU / monitored admission; endocrinology"}]},"name":"Myxedema coma","level":"I","imp":"Myxedema coma","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"titrate (CO2 narcosis risk; low threshold for ventilation)","sc":"زن ۷۵ ساله در زمستان با خواب‌آلودگی، دمای 33°C، HR 48، فشار 85/50، پف دور چشم و ماکروگلوسی.","why":"ثبات راه هوایی، هیدروکورتیزون و T4/T3 بدون انتظار جواب تست."}],"ch":"131","name":"Myxedema coma","name_fa":"کمای میکزدم","cc":["metabolic","altered-mental-status","hypotension-shock"],"keywords":"myxedema coma, hypothyroidism, levothyroxine, liothyronine, hypothermia, hypoventilation, کمای میکزدم, کم کاری تیروئید","status":"draft","features":["نادر و تهدیدکننده حیات؛ محرک: عفونت، سرما، تروما، دارو، MI؛ کلاسیک در زمستان در زن سالمند با هیپوتیروئیدی تشخیص‌داده‌نشده/کم‌درمان","دکمپانساسیون متابولیک و چندارگانی: هیپوترمی، برادیکاردی، هیپوتانسیون، تغییر هوشیاری؛ نارسایی تنفس و CO2 narcosis؛ راه هوایی دشوار (ماکروگلوسی، ادم گلوت و اوروفارنکس)؛ هیپوگلیسمی و هیپوناترمی","شکل 131-1: علائم: ریزش مو، خستگی، افسردگی، تنگی نفس، افزایش وزن، یبوست، بی‌نظمی قاعدگی، ناباروری، گرفتگی عضله، درد مفصل، عدم تحمل سرما؛ نشانه‌ها: پف دور چشم، از دست رفتن ثلث خارجی ابرو، رنگ‌پریدگی، ماکروگلوسی، گرفتگی صدا، هیپوونتیلاسیون، برادیکاردی، کاهش صداهای روده، ادم غیرگودرو، تأخیر شل شدن رفلکس آشیل، نوروپاتی، پوست سرد، خشک و زبر، هیپوترمی","تشخیص بالینی؛ آزمایش تیروئید را بفرست ولی درمان را به تأخیر نینداز؛ FT4 و FT3 پایین و TSH بالا؛ افتراق: سپسیس، افسردگی، بحران آدرنال، CHF، هیپوگلیسمی، سکته، هیپوترمی، منژیت، اوردوز دارو"],"ddx":[{"n":"Sepsis |","cm":1},{"n":"Adrenal crisis |","cm":1},{"n":"Hypothermia (environmental) / hypoglycemia |"},{"n":"Stroke / meningitis / drug overdose / CHF |"}],"redflags":["هیپوترمی، برادیکاردی، هیپوتانسیون، هیپوکاپنی/CO2 narcosis، هیپوگلیسمی، هیپوناترمی"],"guide":"حمایتی: ثبات راه هوایی، تهویه مکانیکی و مانیتور قلبی؛ هیپوتانسیون با مایع (وازوپرسور تا شروع جایگزینی تیروئید ممکن بی‌اثر)؛ گرم کردن پاسیو در هیپوترمی. جستجو و درمان علل محرک؛ hydrocortisone 100 mg IV در شک به نارسایی آدرنال؛ اصلاح هیپوگلیسمی. جایگزینی تیروئید: levothyroxine (T4) 4 µg/kg (بار) سپس 100 µg IV در 24 ساعت و بعد 50 µg IV تا تحمل خوراکی، یا liothyronine (T3) 20 µg IV سپس 10 µg IV هر 8 ساعت تا هوشیاری در میکزدم شدید؛ در سالمند و بیماری قلبی-عروقی حداکثر 10 µg IV شروع؛ هنگام راه رفتن: levothyroxine 50 تا 200 µg/day PO. بستری مانیتورشده/ICU. محرک‌ها: عفونت، آرام‌بخش، بی‌هوشی (etomidate)، سرما، تروما، MI/CHF، CVA، خونریزی GI؛ هیپوکسی، هیپرکاپنی، هیپوناترمی و هیپوگلیسمی.","section":"endocrine","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 131: Thyroid Disease Emergencies, pp. 711–714"},"thyroid-storm":{"id":"thyroid-storm","variants":[{"id":"thyroid-storm-main","o":{"I":[{"t":"CXR portable (heart failure / pneumonia)"}],"L":[{"t":"TSH, free T4, free T3 (clinical diagnosis; do not delay treatment); glucose, electrolytes, BUN, creatinine, liver enzymes, CBC, troponin, calcium; blood / urine cultures if febrile"}],"S":[{"t":"Normal saline / dextrose IV for dehydration ; glucose, multivitamins, thiamine, folate","fl":[{"k":"ci","v":"caution in heart failure"}]},{"t":"Propylthiouracil (PTU) 600–1000 mg PO loading, then 200–250 mg every 4 h  (or methimazole 40 mg PO load then 25 mg every 4 h)","fl":[{"k":"hi","v":""}]},{"t":"At least 1 h after thioamide: Lugol solution 8–10 drops PO every 6–8 h, or potassium iodide 5 drops PO every 6 h (or iopanoic acid 1 g IV every 8 h × 24 h then 500 mg twice daily; lithium carbonate 300 mg PO every 6 h)"},{"t":"Hydrocortisone 100 mg IV then three times daily until stable (or dexamethasone 2 mg every 6 h)"}],"T":[{"t":"Propranolol IV 1–2 mg slow boluses every 10–15 min, or esmolol 500 mcg/kg IV bolus then 50–200 mcg/kg/min","fl":[{"k":"ci","v":"bronchospastic disease; severe heart failure — avoid propranolol / esmolol"}]},{"t":"Cooling for hyperthermia; acetaminophen 325–650 mg PO/PR every 4–6 h; supplemental oxygen; cardiac monitoring"}],"A":[{"t":"Appropriate antibiotics for identified infection"}],"Co":[{"t":"ICU / monitored admission; endocrinology"}]},"name":"Thyroid storm","level":"I","imp":"Thyroid storm","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"if SpO2 < 94%","sc":"زن ۳۵ ساله مبتلا به Graves با تب 40°C، HR 160 (AF)، آژیتاسیون و تعریق شدید پس از عفونت.","why":"بتابلاکر، تیوآمید، ید بعد از 1 ساعت و استروئید؛ علت را بجو."}],"ch":"131","name":"Thyrotoxicosis and thyroid storm","name_fa":"تیروتوکسیکوز و طوفان تیروئیدی","cc":["palpitations","fever","altered-mental-status","metabolic"],"keywords":"thyroid storm, thyrotoxicosis, Graves disease, PTU, methimazole, Lugol, propranolol, esmolol, طوفان تیروئید, تیروتوکسیکوز","status":"draft","features":["hyperthyroidism: عملکرد زیاد غده؛ thyrotoxicosis: هورمون زیاد از هر علت؛ thyroid storm: حالت حاد تهدیدکننده تیروتوکسیکوز، شایع‌تر در Graves","تظاهرات: فعالیت آدرنرژیک افزایش‌یافته (جدول 131-1): عمومی: بی‌حالی، ضعف، عدم تحمل گرما، تعریق، تب، کاهش وزن؛ روان‌عصبی: ناپایداری هیجانی، اضطراب، گیجی، کما، سایکوز، لرزش ظریف، رفلکس زیاد، فلج دوره‌ای؛ چشم: دوبینی، تحریک، lid lag، exophthalmos، افتالموپلژی؛ تیروئید: بزرگی، bruit، حساسیت؛ قلب-ریه: تنگی نفس، تپش، درد قفسه، فشار نبض وسیع، هیپرتانسیون سیستولیک، تاکی‌کاردی سینوسی، AF/فلوتر، CHF؛ GI: اسهال؛ تولیدمثل: الیگومنوره، کاهش میل، منوراژی؛ خون: کم‌خونی، لکوسیتوز؛ پوست: pretibial myxedema (5%)، گرم و مرطوب، اریتم کف دست، onycholysis، ریزش مو","طوفان: علائم اصلی: تب، CNS (آژیتاسیون، گیجی، دلیریوم، استوپور، کما، تشنج) و قلب-عروقی (تاکی‌کاردی، آریتمی، نارسایی قلب)","تشخیص: FT4 یا FT3 بالا و TSH سرکوب‌شده؛ طوفان تشخیص بالینی (تب و تاکی‌کاردی) و آزمایش نمی‌تواند از تیروتوکسیکوز تفکیک کند؛ افتراق: سپسیس، heat stroke، DTs، NMS، سندرم سروتونین، فئوکروموسیتوم، مسمومیت سمپاتومیمتیک"],"ddx":[{"n":"Sepsis |","cm":1},{"n":"Heat stroke / NMS / serotonin syndrome / sympathomimetic overdose |","cm":1},{"n":"Delirium tremens / pheochromocytoma |"}],"redflags":["تب، تاکی‌کاردی شدید، تغییر هوشیاری، نارسایی قلبی"],"guide":"حمایتی: ثبات راه هوایی، اکسیژن، مانیتور؛ خنک‌سازی در هیپرترمی؛ acetaminophen 325 تا 650 mg PO/PR هر 4 تا 6 ساعت؛ مایع IV؛ حمایت تغذیه‌ای: گلوکز، مولتی‌ویتامین، thiamine، فولات. مهار آزادسازی هورمون با تیوآمیدها: PTU بار 600 تا 1000 mg PO سپس 200 تا 250 mg هر 4 ساعت یا methimazole بار 40 mg PO سپس 25 mg هر 4 ساعت (PTU ترجیحی چون تبدیل محیطی T4 به T3 را هم مهار می‌کند). مهار تولید هورمون جدید (حداقل 1 ساعت بعد از تیوآمید): Lugol 8 تا 10 قطره PO هر 6 تا 8 ساعت یا potassium iodide 5 قطره PO هر 6 ساعت یا iopanoic acid IV 1 g هر 8 ساعت در 24 ساعت اول سپس 500 mg دو بار روزانه یا ipodate 0.5 تا 3 g/day × 3 روز یا lithium carbonate 300 mg PO هر 6 ساعت. مسدود کردن β محیطی: propranolol IV بولوس آهسته 1 تا 2 mg هر 10 تا 15 دقیقه یا esmolol 500 mcg/kg بولوس سپس 50 تا 200 mcg/kg/min؛ propranolol 20 تا 120 mg PO در سمیت کمتر؛ در برونکواسپاسم یا CHF شدید اجتناب. جلوگیری از تبدیل محیطی T4 به T3: hydrocortisone 100 mg اولیه سپس سه بار روزانه تا پایداری یا dexamethasone 2 mg هر 6 ساعت. علت محرک: منبع عفونت در تب و آنتی‌بیوتیک مناسب. بستری مانیتورشده/ICU.","section":"endocrine","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 131: Thyroid Disease Emergencies, pp. 711–714"},"adrenal-crisis":{"id":"adrenal-crisis","variants":[{"id":"adrenal-crisis-main","o":{"I":[{"t":"CXR portable (sepsis / pneumonia); imaging as indicated for precipitant"}],"L":[{"t":"Cortisol (draw before steroid if possible; do not delay treatment), ACTH if available; glucose, electrolytes (Na, K), BUN, creatinine, CBC, blood gas, lactate; blood cultures if sepsis suspected"}],"S":[{"t":"Hydrocortisone 100 mg IV  (use dexamethasone 4 mg IV instead if an ACTH stimulation test is planned)","fl":[{"k":"hi","v":""}]},{"t":"D5 normal saline IV (corrects hypoglycemia, hyponatremia, hypotension)","fl":[{"k":"ci","v":"caution in heart failure"}]}],"T":[{"t":"Vasopressors if shock refractory to above; cardiac monitoring; treat hyperkalemia as needed and search for precipitant (infection, steroid withdrawal)"}],"A":[{"t":"Broad-spectrum antibiotics if infection suspected (after cultures)"}],"Co":[{"t":"ICU / monitored admission; endocrinology"}]},"name":"Adrenal crisis","level":"I","imp":"Adrenal crisis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"if SpO2 < 94%","sc":"مرد ۵۵ ساله مصرف‌کننده طولانی prednisone که دارو را قطع کرده، با استفراغ، درد شکم، فشار 70/40، قند 45 و K 5.8.","why":"هیدروکورتیزون IV و D5NS بلافاصله بدون انتظار کورتیزول."},{"id":"adrenal-chronic-steroid-minor-illness","o":{"L":[{"t":"Electrolytes, glucose"}],"T":[{"t":"Triple the daily glucocorticoid dose with prompt follow-up (stress dosing); oral rehydration"}],"Co":[{"t":"Prompt follow-up with endocrinology / primary physician"}]},"name":"Chronic steroid / adrenal insufficiency patient with minor illness or injury","level":"III","imp":"Adrenal insufficiency on chronic steroid therapy with minor illness","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زن ۵۰ ساله با بیماری آدیسون تحت هیدروکورتیزون با گاستروانتریت خفیف و ثبات همودینامیک.","why":"سه برابر کردن دوز و پیگیری."}],"ch":"132","name":"Adrenal insufficiency and adrenal crisis","name_fa":"نارسایی آدرنال و بحران آدرنال","cc":["metabolic","hypotension-shock","weakness","abdominal-pain"],"keywords":"adrenal crisis, Addison disease, adrenal insufficiency, hydrocortisone, steroid withdrawal, Waterhouse-Friderichsen, hyperpigmentation, بحران آدرنال, آدیسون","status":"draft","features":["نیاز فیزیولوژیک به گلوکوکورتیکوئید و مینرالوکورتیکوئید بیش از عرضه قشر آدرنال؛ ACTH و MSH از هیپوفیز؛ ACTH کورتیزول را تحریک می‌کند","اولیه: نارسایی غده آدرنال: کورتیزول و آلدوسترون پایین: ضعف، کم‌آبی، هیپوتانسیون، بی‌اشتهایی، تهوع، استفراغ، کاهش وزن، درد شکم؛ هیپرپیگمانتاسیون پوست و مخاط (MSH + ACTH بدون مهار)","ثانویه: ACTH ناکافی ← کمبود کورتیزول؛ آلدوسترون نرمال (رنین-آنژیوتانسین و پتاسیم) ← بدون هیپرپیگمانتاسیون و هیپرکالمی","بحران آدرنال: شکل حاد تهدیدکننده؛ علائم فوق شدید همراه شوک و تغییر هوشیاری","کورتیزول پلاسما پایین در همه؛ ACTH بالا در اولیه و پایین در ثانویه؛ معمولاً در ED در دسترس نیست: تشخیص اولیه بالینی + هیپوناترمی، هیپرکالمی، هیپوگلیسمی، کم‌خونی، اسیدوز متابولیک، ازوتمی پیش‌کلیوی؛ ثانویه مشابه ولی بدون هیپرکالمی","شایع‌ترین علت حاد: سرکوب آدرنال از مصرف طولانی استروئید با قطع ناگهانی یا استرس (آسیب، بیماری، جراحی)؛ بازگشت محور تا 1 سال طول می‌کشد","جدول 132-1 علل اولیه: خودایمن (polyglandular)، خونریزی/ترومبوز آدرنال (مننگوکوک، Waterhouse–Friderichsen، اختلال انعقاد)، دارو (etomidate، aminoglutethimide، mitotane، ketoconazole)، عفونت (TB، قارچ، AIDS)، انفیلتراتیو (سارکوئیدوز، هموکروماتوز، آمیلوئیدوز، لنفوم، متاستاز)، جراحی (آدرنالکتومی دوطرفه، bariatric)، ارثی (CAH، adrenoleukodystrophy)؛ جدول 132-2 ثانویه: قطع ناگهانی گلوکوکورتیکوئید، نکروز/خونریزی هیپوفیز، تومور مغز، تابش/جراحی هیپوفیز، ضربه سر، Sheehan، انفیلتراتیو و عفونت CNS","در هر بیمار با هیپوتانسیون بی‌توضیح مقاوم به وازوپرسور (به‌ویژه با علت شناخته) به بحران آدرنال فکر کن"],"ddx":[{"n":"Sepsis / septic shock |","cm":1},{"n":"Myocardial infarction / GI bleed |","cm":1},{"n":"Hypothyroidism / hypoglycemia |"},{"n":"Hyperkalemia of other cause |"}],"redflags":["شوک مقاوم به وازوپرسور، هیپوگلیسمی، هیپرکالمی، هیپوناترمی، سابقه استروئید یا مننگوکوک"],"guide":"D5NS مایع انتخابی برای اصلاح هیپوگلیسمی، هیپوناترمی و هیپوتانسیون. hydrocortisone 100 mg IV (اثر گلوکو و مینرالوکورتیکوئیدی)؛ اگر تست تحریک ACTH برنامه‌ریزی شده: dexamethasone 4 mg IV (بر تست اثر نمی‌گذارد). وازوپرسور اگر شوک مقاوم. بیمار مصرف‌کننده مزمن استروئید با بیماری/آسیب خفیف: دوز گلوکوکورتیکوئید روزانه را سه برابر و پیگیری سریع.","section":"endocrine","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 132: Adrenal Insufficiency, pp. 715–718"}});
